using CodigoActivo.Domain.Users;
using CodigoActivo.Infrastructure.Database.Configurations;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace CodigoActivo.Infrastructure.Users;

/// <summary>
/// Defines the Entity Framework mapping for the changes of the news consent of a user.
/// </summary>
public class NewsConsentChangeConfiguration : IEntityTypeConfiguration<NewsConsentChange>
{
    /// <summary>
    /// Name of the shadow key, generated by the database in insertion order, which also orders
    /// the changes a user made at the same instant.
    /// </summary>
    public const string Sequence = "Id";

    /// <summary>
    /// Configures the database mapping for the changes of the news consent.
    /// </summary>
    /// <param name="builder">Entity Framework builder used to configure the mapped type.</param>
    public void Configure(EntityTypeBuilder<NewsConsentChange> builder)
    {
        builder.HasHistory();
        builder.Property<long>(Sequence).ValueGeneratedOnAdd();
        builder.HasKey(Sequence);

        builder.Property(x => x.Granted).IsRequired();
        builder.Property(x => x.Source).HasConversion<string>().HasMaxLength(32).IsRequired();
        builder.Property(x => x.ChangedAt).IsRequired();

        builder.HasIndex(x => x.UserId);

        builder
            .HasOne<User>()
            .WithMany(u => u.NewsConsentChanges)
            .HasForeignKey(x => x.UserId)
            .OnDelete(DeleteBehavior.ClientCascade);
    }
}
